<template>
<div class="my-popups">
    <loader :is-visible="isLoading"></loader>

    <div class="modal my-popups right fade d-block" :class="{ show: isShown }">
        <div role="document" class="modal-dialog" style="max-width: 1000px !important;">
            <div class="modal-content">
                <div class="modal-header theme-primary partition-full d-flex">
                    <h4 class="modal-title">{{ modalTitle }}</h4>
                    <button type="button" class="close" v-on:click="Close">
                        <em class="fa fa-times" aria-hidden="true"></em>
                    </button>
                </div>

                <div class="modal-body">
                    <div class="pt-2 d-inline-block w-100">
                        <div class="col-12 p-0 mt-0">
                            <div class="col-6 col-sm-6 col-md-6 col-lg-6 col-xl-6 float-left pr-1 pl-0">
                                <input
                                    id="txtAvailableBillerSearch"
                                    maxlength="50"
                                    class="form-control"
                                    type="text"
                                    v-model="Searchtext"
                                    placeholder="Search by Biller Name."
                                    autocomplete="off"
                                    @keyup.enter="SearchButton(Searchtext)">
                            </div>
                            <div class="col-6 col-sm-6 col-md-6 col-lg-6 col-xl-6 float-left pl-0">
                                <div class="search-btm-btn background-0  form-check-inline">
                                    <button title="Search" type="button" @click="SearchButton(Searchtext)" class="btn btn-success mr-1 px-4" data-original-title="Search">
                                        <em class="fa fa-search"></em> Search
                                    </button>
                                    <button title="Clear" type="button" class="btn btn-danger px-4" @click="Clear()" data-original-title="Clear">
                                        <em class="fa fa-refresh"></em> Clear
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>

                    <div class="listing">
                        <div class="table-responsive table-fix-header">
                            <table class="table table-bordered">
                                <thead class="thead-bg">
                                    <tr>
                                        <th style="width:5%" class="text-center">
                                            <label class="form-check form-check-inline">
                                                <div class="custom-control custom-checkbox custom-control-inline">
                                                    <input type="checkbox" id="availableBillerCheckAll" class="chkitems1 custom-control-input" :checked="selectAll" @change="selectAllItems" name="selectedItems1">
                                                    <label class="custom-control-label" for="availableBillerCheckAll"></label>
                                                </div>
                                            </label>
                                        </th>
                                        <th scope="col" class="cursor-pointer" @click="sortdata('USERNAME')">
                                            <div class="d-flex justify-content-between align-items-center">
                                                <span>{{ $t('BillerName') }}</span>
                                                <span><em class="fa" :class="SortBy === 'USERNAME' ? (SortExp === 'ASC' ? 'fa-sort-up' : 'fa-sort-down') : 'fa-sort'"></em></span>
                                            </div>
                                        </th>
                                        <th scope="col">{{ $t('Email') }}</th>
                                        <th scope="col">{{ $t('DepartmentName') }}</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    <tr v-for="(item,index) in BillerData" :key="'biller-' + item.USERID + '-' + index">
                                        <td class="text-center">
                                            <label class="form-check form-check-inline">
                                                <div class="custom-control custom-checkbox custom-control-inline">
                                                    <input type="checkbox" :id="'availableBillerRow' + index" class="chkitems custom-control-input" v-model="selectedItems" @change="updateSelectAll" name="selectedItems" :value="item.USERID">
                                                    <label class="custom-control-label" :for="'availableBillerRow' + index"></label>
                                                </div>
                                            </label>
                                        </td>
                                        <td>
                                            <div class="text" :title="stripHtml(rowDisplayText(item))" v-html="rowDisplayHtml(item)"></div>
                                        </td>
                                        <td>
                                            <div class="text" :title="item.EMAIL_ID" v-html="item.EMAIL_ID"></div>
                                        </td>
                                        <td>
                                           <div
                                            class="text"
                                            :title="item.DEPARTMENT_NAME ? item.DEPARTMENT_NAME : '--'"
                                            v-html="item.DEPARTMENT_NAME ? item.DEPARTMENT_NAME : '--'">
                                            </div>
                                        </td>
                                    </tr>

                                    <tr v-if="!BillerData || BillerData.length === 0">
                                        <td colspan="2" class="text-danger text-center border-0">
                                            {{ $t("NorecordfoundText") }}
                                        </td>
                                    </tr>
                                </tbody>
                            </table>
                        </div>

                        <dynamic-form
                            lang="en"
                            ref="AvailableBillerForm"
                            :buttons="buttons"
                            :schema="FormSchema"
                            v-on:OnSubmit="onSubmit"
                            :mandatorytext="MandatoryString">
                        </dynamic-form>
                    </div>
                </div>
            </div>
        </div>
    </div>
</div>
</template>

<script>
import DataService from '../../services/DataService';

export default {
    components: {},
    props: {
        /** USERIDs already on the Assign Contract grid — omitted until that row is deleted */
        excludeUserIds: {
            type: Array,
            default: () => []
        }
    },
    computed: {
        modalTitle() {
            const k = this.$t('AvailableBillers');
            return k === 'AvailableBillers' ? 'Available Billers' : k;
        },
        excludeUserIdSet() {
            return new Set((this.excludeUserIds || []).map(id => Number(id)).filter(n => !isNaN(n)));
        }
    },
    watch: {
        excludeUserIds: {
            deep: true,
            handler() {
                this.applyPagedView();
            }
        }
    },
    data() {
        return {
            isLoading: false,
            isShown: false,
            allBillersRaw: [],
            BillerData: [],
            selectedItems: [],
            selectAll: false,
            SortBy: '',
            SortExp: '',
            searchCondition: '',
            Searchtext: '',
            FormSchema: [],
            MandatoryString: 'Fields marked with an asterisk (*) are mandatory.',
            buttons: [{
                type: 'submit',
                class: 'btn btn-success',
                text: "<i class='fa fa-save pr-2'></i>Next",
                isVisible: true
            },
            {
                type: 'button',
                class: 'btn btn-danger',
                text: "<i class='fa fa-close pr-2'></i>Cancel",
                onClick: this.Close
            }]
        };
    },
    mounted() {
        this.$nextTick(() => {
            setTimeout(() => {
                this.isShown = true;
            }, 50);
        });
    },
    created: async function () {
        await this.loadBillers();
        this.applyPagedView();
    },
    methods: {
        stripHtml(s) {
            if (!s) return '';
            return String(s).replace(/<[^>]+>/g, ' ');
        },
        rowDisplayText(item) {
            const status = this.getBillerStatusLabel(item);
            const base = `${item.USERNAME || ''}`;
            return status ? `${base} (${status})` : base;
        },
        rowDisplayHtml(item) {
            const status = this.getBillerStatusLabel(item);
            const esc = (t) => String(t == null ? '' : t)
                .replace(/&/g, '&amp;')
                .replace(/</g, '&lt;')
                .replace(/>/g, '&gt;');
            const base = `${esc(item.USERNAME)}`;
            if (!status) return base;
            const cls = /inactive/i.test(status) ? 'text-danger' : 'text-success';
            return `${base} <span class="${cls}">(${esc(status)})</span>`;
        },
        getBillerStatusLabel(item) {
            if (!item) return '';
            const s = item.STATUS ?? item.STATUS_NAME ?? item.UserStatus ?? item.USER_STATUS;
            if (s != null && String(s).trim() !== '') return String(s).trim();
            if (item.IS_ACTIVE === true || item.IS_ACTIVE === 'Y' || item.IS_ACTIVE === 1) return 'Active';
            if (item.IS_ACTIVE === false || item.IS_ACTIVE === 'N' || item.IS_ACTIVE === 0) return 'Inactive';
            return '';
        },
        async loadBillers() {
            const vm = this;
            vm.isLoading = true;
            try {
                const url = 'reqFrom=all&moduleName=Billing&IncludeBiller=YES';
                const res = await DataService.GetBillerList(url);
                const parsed = JSON.parse(res.data.result);
                vm.allBillersRaw = Array.isArray(parsed) ? parsed : [];
            } catch (e) {
                console.error('AvailableBiller loadBillers:', e);
                vm.allBillersRaw = [];
            } finally {
                vm.isLoading = false;
            }
        },
        getFilteredList() {
            const vm = this;
            let list = (vm.allBillersRaw || []).filter(x => x != null);
            const ex = vm.excludeUserIdSet;
            if (ex.size) {
                list = list.filter(b => !ex.has(Number(b.USERID)));
            }
            const q = (vm.searchCondition || '').trim().toLowerCase();
            if (q) {
                list = list.filter(b => {
                    const u = (b.USERNAME || '').toString().toLowerCase();
                    const id = (b.USERID != null ? String(b.USERID) : '');
                    return u.includes(q) || id.includes(q);
                });
            }
            if (vm.SortBy === 'USERNAME') {
                const dir = vm.SortExp === 'ASC' ? 1 : -1;
                list = list.sort((a, b) => {
                    const nameA = (a.USERNAME || '').toString().toLowerCase();
                    const nameB = (b.USERNAME || '').toString().toLowerCase();
                    if (nameA < nameB) return -1 * dir;
                    if (nameA > nameB) return 1 * dir;
                    return 0;
                });
            }
            return list;
        },
        applyPagedView() {
            const vm = this;
            const list = vm.getFilteredList();
            vm.BillerData = list;
            vm.updateSelectAll();
        },
        GetBillerPage() {
            this.applyPagedView();
        },
        sortdata(sortBy) {
            this.SortBy = sortBy;
            let sortExp = 'ASC';
            if (this.SortExp === 'ASC') {
                sortExp = 'DESC';
            }
            this.SortExp = sortExp;
            this.applyPagedView();
        },
        SearchButton() {
            this.searchCondition = (this.Searchtext || '').trim();
            this.applyPagedView();
        },
        Clear() {
            this.Searchtext = '';
            this.searchCondition = '';
            this.applyPagedView();
        },

        selectAllItems() {
            const vm = this;
            vm.selectAll = !vm.selectAll;
            if (vm.selectAll) {
                vm.BillerData.forEach(function (item) {
                    const uid = item.USERID;
                    if (!vm.selectedItems.some(s => Number(s) === Number(uid))) {
                        vm.selectedItems.push(uid);
                    }
                });
            } else {
                const pageIds = vm.BillerData.map(x => Number(x.USERID));
                vm.selectedItems = vm.selectedItems.filter(id => !pageIds.includes(Number(id)));
            }
        },
        updateSelectAll() {
            const vm = this;
            const totalItems = vm.BillerData.length;
            if (!totalItems) {
                vm.selectAll = false;
                return;
            }
            const selectedOnPage = vm.BillerData.filter(x =>
                vm.selectedItems.some(s => Number(s) === Number(x.USERID))
            ).length;
            vm.selectAll = selectedOnPage === totalItems;
        },
        onSubmit(formfields) {
            const vm = this;
            vm.buttons[0].class = 'btn btn-success disabled';
            vm.isLoading = true;
            if (vm.selectedItems && vm.selectedItems.length) {
                const set = new Set(vm.selectedItems.map(id => Number(id)));
                const assignBiller = vm.allBillersRaw.filter(x => set.has(Number(x.USERID)));
                const payload = {
                    formfields: formfields,
                    AssignBiller: assignBiller
                };
                vm.$emit('submit-data', payload);
                vm.isLoading = false;
            } else {
                vm.isLoading = false;
                vm.ShowAlert(vm.$t('Selectanyrecordtodelete'));
            }
        },
        Close() {
            if (this.$parent && this.$parent.isAddBillerPopup !== undefined) {
                this.$parent.isAddBillerPopup = false;
            }
            this.$emit('close');
        }
    }
};
</script>

<style>
.available-biller-popup .ticketsmallfix {
    display: none;
}
</style>
